#[tokio::test]
async fn share_acknowledge_unknown_topic_or_partition_does_not_retry() {
    let mock = common::Mock::start().await;
    v2(&mock);
    produce(&mock, &[(0, b"held")]).await;
    let mut group = ShareGroup::join(config(&mock), "ack-unk-tp", "t")
        .await
        .unwrap();
    let recs = group.poll().await.unwrap();
    assert_eq!(recs.len(), 1);
    let seen = Arc::new(Mutex::new(Vec::new()));
    let seen_cb = seen.clone();
    group.set_acknowledgement_commit_callback(move |_, exception| {
        seen_cb
            .lock()
            .push(exception.as_ref().and_then(|error| error.code()));
    });
    mock.fail_share_ack_once("t", 0, error::UNKNOWN_TOPIC_OR_PARTITION);
    group.accept(&recs).await.unwrap();
    let calls = mock.share_ack_calls();
    let results = group.commit_sync().await.unwrap();
    assert_eq!(results.len(), 1);
    assert_eq!(
        results[0].1.as_ref().and_then(|error| error.code()),
        Some(error::UNKNOWN_TOPIC_OR_PARTITION),
        "Java testFatalErrorsAcknowledgementResponse completes UNKNOWN_TOPIC_OR_PARTITION"
    );
    assert_eq!(
        mock.share_ack_calls(),
        calls + 1,
        "UNKNOWN_TOPIC_OR_PARTITION must not retry ShareAcknowledge"
    );
    assert_eq!(*seen.lock(), vec![Some(error::UNKNOWN_TOPIC_OR_PARTITION)]);
    let empty = group.commit_sync().await.unwrap();
    assert!(
        empty.is_empty(),
        "completed fatal acks must not stay pending"
    );
    group.leave().await.unwrap();
}

