    let mock = common::Mock::start().await;
    v2(&mock);
    produce(&mock, &[(0, b"held")]).await;
    let mut group = ShareGroup::join(config(&mock), "ack-omit", "t")
        .await
        .unwrap();
    let recs = group.poll().await.unwrap();
    assert_eq!(recs.len(), 1);
    let seen = Arc::new(Mutex::new(Vec::new()));
    let seen_cb = seen.clone();
    group.set_acknowledgement_commit_callback(move |_, exception| {
        seen_cb.lock().push(
            exception
                .as_ref()
                .map(|error| (error.code(), error.message().to_owned())),
        );
    });
    group.accept(&recs).await.unwrap();
    let version = mock.last_share_fetch_version().unwrap_or(2);
    let mut injected = BytesMut::new();
    encode_share_acknowledge_topics_response(&mut injected, version, 0, &[]).unwrap();
    mock.inject_share_ack_response_once(&injected);
    let calls = mock.share_ack_calls();
    let results = group.commit_sync().await.unwrap();
    assert_eq!(results.len(), 1);
    assert_eq!(
        results[0].1.as_ref().and_then(|error| error.code()),
        Some(error::INVALID_RECORD_STATE),
        "Java testShareAcknowledgeInvalidResponse completes omitted partitions"
    );
    assert_eq!(
        results[0].1.as_ref().map(|error| error.message()),
        Some("Acknowledgement not successful due to invalid response from broker")
    );
